#include "stdlib/stats/base/dists/hypergeometric/quantile.h"
#include "stdlib/stats/base/dists/hypergeometric/cdf.h"
#include "stdlib/math/base/assert/is_nan.h"
#include "stdlib/math/base/assert/is-nonnegative-integer.h"
#include "stdlib/math/base/special/max.h"
#include "stdlib/math/base/special/min.h"
#include "stdlib/constants/float64/pinf.h"
#include <stdint.h>

/**
* Evaluates the quantile function for a hypergeometric distribution with population size `N`, subpopulation size `K`, and number of draws `n` at a probability `p`.
*
* @param p   input value
* @param N   population size
* @param K   subpopulation size
* @param n   number of draws
* @return evaluated quantile function
*
* @example
* double y = stdlib_base_dists_hypergeometric_quantile( 0.4, 40.0, 20.0, 10.0 );
* // returns 5.0
*/
double stdlib_base_dists_hypergeometric_quantile( const double p, const double N, const double K, const double n ) {
	double prob;
	double x;

	if (
		stdlib_base_is_nan( p ) ||
		stdlib_base_is_nan( N ) ||
		stdlib_base_is_nan( K ) ||
		stdlib_base_is_nan( n ) ||
		!stdlib_base_is_nonnegative_integer( N ) ||
		!stdlib_base_is_nonnegative_integer( K ) ||
		!stdlib_base_is_nonnegative_integer( n ) ||
		N == STDLIB_CONSTANT_FLOAT64_PINF ||
		K == STDLIB_CONSTANT_FLOAT64_PINF ||
		K > N ||
		n > N ||
		p < 0.0 ||
		p > 1.0
	) {
		return 0.0 / 0.0; // NaN
	}
	if ( p == 0.0 ) {
		return stdlib_base_max( 0.0, n + K - N );
	}
	if ( p == 1.0 ) {
		return stdlib_base_min( n, K );
	}
	x = stdlib_base_max( 0.0, n + K - N );
	while ( 1 ) {
		prob = stdlib_base_dists_hypergeometric_cdf( x, N, K, n );
		if ( prob > p ) {
			break;
		}
		x += 1.0;
	}
	return x;
}
